import { DEEPSEEK_MODELS } from "../config";
import { aiSignal, observeAiDispatch } from "../telemetry-runtime";
import { openAIUsage } from "./usage";
import { collectHttpTextStream } from "./text-stream";
import {
  LLMAdapter,
  NormalizedMessage,
  NormalizedTool,
  LLMResponse,
  LLMProviderError,
  NormalizedToolCall,
} from "./types";
import crypto from "crypto";

export interface DeepSeekAdapterOptions {
  onTextDelta?: (text: string) => void;
  responseFormat?: "json_object" | "text";
  temperature?: number;
  maxTokens?: number;
  /**
   * Toggles DeepSeek's thinking/reasoning mode for models that support it
   * (deepseek-chat / deepseek-reasoner, V3.1+). "disabled" skips generating
   * and billing reasoning tokens — used for simple/fast tiers. Rejected policies fail explicitly;
   * callers own recovery instead of silently restoring default reasoning.
   */
  thinking?: "enabled" | "disabled";
  /** Omission preserves existing routing/provider defaults. */
  reasoningEffort?: "low" | "high" | "max";
  /** Aborts the upstream HTTP request immediately when signalled. */
  signal?: AbortSignal;
  /** Caller owns the bounded repair/fallback budget. */
  singleAttempt?: boolean;
  telemetry?: boolean;
  telemetryStage?: string;
  retryIndex?: number;
}

export class DeepSeekAdapter implements LLMAdapter {
  private apiKey: string;
  private model: string;
  private baseURL: string;

  constructor(
    apiKey: string,
    model: string = DEEPSEEK_MODELS.default,
    baseURL: string = process.env.DEEPSEEK_BASE_URL || "https://api.deepseek.com"
  ) {
    // Sanitize API key and baseURL against zero-width spaces (\u200B) or non-ASCII characters
    this.apiKey = (apiKey || "").replace(/[^\x20-\x7E]/g, "").trim();
    this.model = model;
    this.baseURL = (baseURL || "https://api.deepseek.com")
      .replace(/[^\x20-\x7E]/g, "")
      .trim()
      .replace(/\/+$/, "");
  }

  public getModel(): string {
    return this.model;
  }

  public resolveModelName(requested: string): string {
    if (process.env.DEEPSEEK_MODEL) return process.env.DEEPSEEK_MODEL;
    return requested || DEEPSEEK_MODELS.default;
  }

  private mapTool(tool: NormalizedTool): any {
    return {
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters || { type: "object", properties: {} },
      },
    };
  }

  private mapMessages(
    messages: NormalizedMessage[],
    systemInstruction: string,
    includeReasoning = false
  ): any[] {
    const deepSeekMessages: any[] = [];

    // DeepSeek OpenAI-compatible standard requires system message
    if (systemInstruction && systemInstruction.trim().length > 0) {
      deepSeekMessages.push({
        role: "system",
        content: systemInstruction.trim(),
      });
    }

    for (const msg of messages) {
      if (msg.role === "system") {
        if (msg.content) {
          deepSeekMessages.push({ role: "system", content: msg.content });
        }
        continue;
      }

      if (msg.role === "user") {
        const hasMedia = msg.parts?.some((p) => !!(p.inlineData || p.imageUrl));

        if (hasMedia && msg.parts) {
          const contentParts: any[] = [];
          for (const p of msg.parts) {
            if (p.text) {
              contentParts.push({ type: "text", text: p.text });
            }
            if (p.inlineData || p.imageUrl) {
              contentParts.push({
                type: "image_url",
                image_url: {
                  url: p.imageUrl ?? `data:${p.inlineData!.mimeType};base64,${p.inlineData!.data}`,
                  detail: "original",
                },
              });
            }
          }
          if (msg.content && !msg.parts.some((p) => p.text === msg.content)) {
            contentParts.unshift({ type: "text", text: msg.content });
          }
          deepSeekMessages.push({ role: "user", content: contentParts });
        } else {
          let text = msg.content || "";
          if (msg.parts) {
            const partsText = msg.parts
              .map((p) => p.text)
              .filter(Boolean)
              .join("\n");
            if (partsText) {
              text = text ? `${text}\n${partsText}` : partsText;
            }
          }
          deepSeekMessages.push({ role: "user", content: text || " " });
        }
      } else if (msg.role === "assistant") {
        // Thinking tool rounds require the provider's reasoning on the next wire
        // request. Keep it in memory only; never expose or persist it in chat.
        const reasoning = includeReasoning ? { reasoning_content: (msg.rawParts ?? [])
          .filter(part => part.type === "reasoning" && typeof part.text === "string")
          .map(part => part.text).join("") } : {};
        if (msg.toolCalls && msg.toolCalls.length > 0) {
          deepSeekMessages.push({
            role: "assistant",
            ...reasoning,
            content: msg.content || null,
            tool_calls: msg.toolCalls.map((tc) => ({
              id: tc.id || `call_${crypto.randomUUID().slice(0, 8)}`,
              type: "function",
              function: {
                name: tc.name,
                arguments:
                  typeof tc.args === "string"
                    ? tc.args
                    : JSON.stringify(tc.args || {}),
              },
            })),
          });
        } else {
          deepSeekMessages.push({
            role: "assistant",
            ...reasoning,
            content: msg.content || "",
          });
        }
      } else if (msg.role === "tool") {
        if (msg.toolResults && msg.toolResults.length > 0) {
          for (const tr of msg.toolResults) {
            deepSeekMessages.push({
              role: "tool",
              tool_call_id: tr.toolCallId,
              name: tr.name,
              content:
                typeof tr.result === "string"
                  ? tr.result
                  : JSON.stringify(tr.result),
            });
          }
        }
      }
    }

    return deepSeekMessages;
  }

  async generateResponse(
    messages: NormalizedMessage[],
    systemInstruction: string,
    tools: NormalizedTool[] = [],
    options?: DeepSeekAdapterOptions
  ): Promise<LLMResponse> {
    if (!this.apiKey) {
      throw new LLMProviderError(
        "deepseek",
        "DEEPSEEK_API_KEY is not configured.",
        null,
        "missing_api_key"
      );
    }

    const deepSeekMessages = this.mapMessages(messages, systemInstruction, tools.length > 0 && options?.thinking !== "disabled");
    const deepSeekTools =
      tools.length > 0 ? tools.map((t) => this.mapTool(t)) : undefined;

    const targetModel = this.resolveModelName(this.model);
    if (messages.some(message => message.parts?.some(part => part.inlineData || part.imageUrl)) && !/^(?:deepseek-flash|deepseek-v4-flash(?:-vision-exp)?)$/.test(targetModel)) {
      throw new LLMProviderError("deepseek", "The selected DeepSeek model does not support images. Choose DeepSeek Flash or Auto.", null, "unsupported_media");
    }
    const payload: Record<string, any> = {
      model: targetModel,
      messages: deepSeekMessages,
      stream: Boolean(options?.onTextDelta && !tools.length && options.responseFormat !== "json_object"),
    };
    if (payload.stream) payload.stream_options = { include_usage: true };

    if (deepSeekTools && deepSeekTools.length > 0) {
      payload.tools = deepSeekTools;
      payload.tool_choice = "auto";
    }

    if (options?.responseFormat === "json_object") {
      payload.response_format = { type: "json_object" };
    }

    if (typeof options?.temperature === "number") {
      payload.temperature = options.temperature;
    }

    payload.max_tokens = options?.maxTokens ?? 16384;

    if (options?.thinking) {
      payload.thinking = { type: options.thinking };
    }
    if (options?.reasoningEffort) payload.reasoning_effort = options.reasoningEffort;

    const doRequest = async (reqPayload: Record<string, any>): Promise<any> => observeAiDispatch("deepseek", targetModel, async () => {
      const endpoint = `${this.baseURL}/chat/completions`;
      const response = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify(reqPayload),
        signal: aiSignal(options?.signal),
      });

      if (!response.ok) {
        let errorBody = "";
        try {
          errorBody = await response.text();
        } catch {
          // ignore
        }

        const statusCode = response.status;
        let errorCode = "api_error";
        if (statusCode === 401) errorCode = "unauthorized";
        else if (statusCode === 429) errorCode = "rate_limit";
        else if (statusCode >= 500) errorCode = "server_error";

        const err = new LLMProviderError(
          "deepseek",
          `DeepSeek API responded with HTTP ${statusCode}`,
          errorBody,
          errorCode
        ) as LLMProviderError & { status: number };
        err.status = statusCode;
        throw err;
      }

      return payload.stream && options?.onTextDelta
        ? collectHttpTextStream(response, options.onTextDelta, aiSignal(options.signal))
        : response.json();
    }, data => ({ model: data.model, usage: openAIUsage(data.usage), finishReason: data.choices?.[0]?.finish_reason }), options?.telemetry !== false, { stage: options?.telemetryStage, retryIndex: options?.retryIndex });

    try {
      const data = await doRequest(payload);

      const choice = data.choices?.[0];
      const message = choice?.message;

      if (!message) {
        throw new LLMProviderError(
          "deepseek",
          "DeepSeek API returned an empty choices array.",
          data,
          "empty_response"
        );
      }

      const normalizedToolCalls: NormalizedToolCall[] = [];
      if (message.tool_calls && Array.isArray(message.tool_calls)) {
        for (const tc of message.tool_calls) {
          let parsedArgs: Record<string, any> = {};
          try {
            parsedArgs =
              typeof tc.function?.arguments === "string"
                ? JSON.parse(tc.function.arguments || "{}")
                : tc.function?.arguments || {};
          } catch (err) {
            throw new LLMProviderError(
              "deepseek",
              `Failed to parse tool call arguments for tool '${tc.function?.name}'`,
              err,
              "invalid_json"
            );
          }

          normalizedToolCalls.push({
            id: tc.id || crypto.randomUUID(),
            name: tc.function?.name || "",
            args: parsedArgs,
          });
        }
      }

      const rawText = message.content || "";
      const reasoningContent = message.reasoning_content;

      // Retained only for in-memory tool continuation, never logs or user text.
      const text = rawText ? rawText.trim() : undefined;

      return {
        finishReason: data.choices?.[0]?.finish_reason === "length" ? "MAX_TOKENS" :
          ["stop", "tool_calls"].includes(data.choices?.[0]?.finish_reason) ? "STOP" : "OTHER",
        text,
        toolCalls:
          normalizedToolCalls.length > 0 ? normalizedToolCalls : undefined,
        rawCandidateParts: reasoningContent
          ? [{ text: reasoningContent, type: "reasoning" }]
          : undefined,
        usage: openAIUsage(data.usage),
      };
    } catch (err: any) {
      if (err instanceof LLMProviderError) {
        throw err;
      }
      throw new LLMProviderError(
        "deepseek",
        "DeepSeek network or execution error",
        err,
        "network_error"
      );
    }
  }
}

import { aiSignal, observeAiDispatch } from "../telemetry-runtime";
import { openAIUsage } from "./usage";
import { collectTextChunks } from "./text-stream";
import Groq from "groq-sdk";
import { LLMAdapter, NormalizedMessage, NormalizedTool, LLMResponse, LLMProviderError, NormalizedToolCall } from "./types";
import crypto from "crypto";

export class GroqAdapter implements LLMAdapter {
  private groq: Groq;
  private model: string;

  constructor(apiKey: string, model: string = process.env.GROQ_MODEL || "openai/gpt-oss-120b") {
    this.groq = new Groq({ apiKey });
    this.model = model;
  }

  private mapTool(tool: NormalizedTool): any {
    return {
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters || { type: "object", properties: {} },
      },
    };
  }

  private mapMessages(messages: NormalizedMessage[], systemInstruction: string): any[] {
    const groqMessages: any[] = [];

    // Groq requires system instruction as the first message
    groqMessages.push({ role: "system", content: systemInstruction });

    for (const msg of messages) {
      if (msg.role === "system") continue;

      if (msg.role === "user") {
        if (msg.parts && msg.parts.some((p) => p.inlineData)) {
          const contentParts: any[] = [];
          for (const p of msg.parts) {
            if (p.text) contentParts.push({ type: "text", text: p.text });
            if (p.inlineData) {
              contentParts.push({
                type: "image_url",
                image_url: {
                  url: `data:${p.inlineData.mimeType};base64,${p.inlineData.data}`,
                },
              });
            }
          }
          if (contentParts.length === 0 && msg.content) {
            contentParts.push({ type: "text", text: msg.content });
          }
          groqMessages.push({ role: "user", content: contentParts });
        } else {
          let content = msg.content || "";
          if (msg.parts) {
            for (const p of msg.parts) {
              if (p.text) content += (content ? "\n" : "") + p.text;
            }
          }
          groqMessages.push({ role: "user", content: content || " " });
        }
      } else if (msg.role === "assistant") {
        if (msg.toolCalls) {
          groqMessages.push({
            role: "assistant",
            content: msg.content || "",
            tool_calls: msg.toolCalls.map(tc => ({
              id: tc.id,
              type: "function",
              function: { name: tc.name, arguments: JSON.stringify(tc.args) }
            }))
          });
        } else {
          groqMessages.push({ role: "assistant", content: msg.content || "" });
        }
      } else if (msg.role === "tool") {
        if (msg.toolResults) {
          for (const tr of msg.toolResults) {
            groqMessages.push({
              role: "tool",
              tool_call_id: tr.toolCallId,
              name: tr.name,
              content: typeof tr.result === "string" ? tr.result : JSON.stringify(tr.result),
            });
          }
        }
      }
    }

    return groqMessages;
  }

  async generateResponse(
    messages: NormalizedMessage[],
    systemInstruction: string,
    tools: NormalizedTool[],
    options?: import("./types").LLMGenerateOptions
  ): Promise<LLMResponse> {
    const groqMessages = this.mapMessages(messages, systemInstruction);
    const groqTools = tools.length > 0 ? tools.map(this.mapTool) : undefined;

    const candidateModels = options?.singleAttempt || messages.some(m => m.parts?.some(p => p.inlineData)) ? [this.model] : Array.from(
      new Set(
        [
          this.model,
          process.env.GROQ_MODEL,
          "openai/gpt-oss-120b",
          "openai/gpt-oss-20b",
        ].filter(Boolean) as string[]
      )
    );

    let lastError: any = null;

    for (const [retryIndex, modelToTry] of candidateModels.entries()) {
      try {
        const completion = await observeAiDispatch("groq", modelToTry, async () => {
          const response = await this.groq.chat.completions.create({
          model: modelToTry,
          messages: groqMessages,
          tools: groqTools,
          tool_choice: groqTools ? "auto" : undefined,
          response_format:
            options?.responseFormat === "json_object"
              ? { type: "json_object" }
              : undefined,
          temperature: options?.temperature,
          max_tokens: options?.maxTokens ?? 16384,
          stream: Boolean(options?.onTextDelta && modelToTry.startsWith("openai/gpt-oss-") && !tools.length && options.responseFormat !== "json_object"),
          // GPT-OSS retains reasoning; its minimum supported effort is low.
          ...(modelToTry.startsWith("openai/gpt-oss-") ? { reasoning_effort: options?.thinking === "disabled" ? "low" as const : options?.reasoningEffort === "max" ? "high" as const : options?.reasoningEffort } : {}),
        }, {
          signal: aiSignal(options?.signal), maxRetries: 0,
          });
          return Symbol.asyncIterator in response
            ? collectTextChunks(response, options!.onTextDelta!) : response;
        }, completion => ({ model: completion.model, usage: openAIUsage(completion.usage as unknown as Record<string, unknown>), finishReason: completion.choices?.[0]?.finish_reason }), options?.telemetry !== false, { stage: options?.telemetryStage, retryIndex: (options?.retryIndex ?? 0) + retryIndex });

        const responseMessage = completion.choices[0].message;
        const normalizedToolCalls: NormalizedToolCall[] = [];

        // 1. Standard Tool Calls
        if (responseMessage.tool_calls && responseMessage.tool_calls.length > 0) {
          for (const tc of responseMessage.tool_calls) {
            let args = {};
            try {
              args = JSON.parse(tc.function.arguments || "{}");
            } catch (e) {
              throw new LLMProviderError("groq", "Failed to parse tool arguments from Groq", e, "invalid_json");
            }
            normalizedToolCalls.push({
              id: tc.id,
              name: tc.function.name,
              args,
            });
          }
        }
        // 2. Llama-3 XML Recovery Logic
        else if (responseMessage.content && responseMessage.content.includes("<function")) {
          const matches = [...responseMessage.content.matchAll(/<function[=(](\w+)[=)>]*([\s\S]*?)<\/function>/gi)];
          for (const match of matches) {
            const toolName = match[1];
            const rawArgs = match[2];
            let args = {};
            try {
              const cleanedArgs = rawArgs.replace(/^[=\s>]+/, "").trim();
              args = JSON.parse(cleanedArgs || "{}");
            } catch (err: any) {
               // We swallow parsing errors here to let it fail upstream gracefully
            }
            normalizedToolCalls.push({
              id: crypto.randomUUID(), // Groq didn't provide one since it hallucinated
              name: toolName,
              args,
            });
          }
        }

        const rawContent = responseMessage.content || undefined;
        const cleanContent = rawContent ? rawContent.replace(/<think>[\s\S]*?<\/think>/gi, "").trim() : undefined;

        return {
          finishReason: completion.choices?.[0]?.finish_reason === "length" ? "MAX_TOKENS" :
            ["stop", "tool_calls"].includes(completion.choices?.[0]?.finish_reason ?? "") ? "STOP" : "OTHER",
          text: cleanContent || undefined,
          toolCalls: normalizedToolCalls.length > 0 ? normalizedToolCalls : undefined,
          usage: openAIUsage(completion.usage as unknown as Record<string, unknown>),
        };
      } catch (error: any) {
        lastError = error;

        // Handle the Llama-3 400 error where it throws raw XML back at the API
        const groqInnerError = error.error?.error;
        if (!options?.singleAttempt && groqInnerError?.code === "tool_use_failed" && groqInnerError?.failed_generation) {
          const failedGen = groqInnerError.failed_generation;
          const match = failedGen.match(/<function[=(](\w+)[=)>]*([\s\S]*?)<\/function>/i);
          if (match) {
            const toolName = match[1];
            const rawArgs = match[2];
            let args = {};
            try {
              const cleanedArgs = rawArgs.replace(/^[=\s>]+/, "").trim();
              args = JSON.parse(cleanedArgs || "{}");
            } catch (e) {}

            return {
              toolCalls: [{
                id: crypto.randomUUID(),
                name: toolName,
                args,
              }]
            };
          }
        }

        // If error is model_not_found, 404, or decommissioned, try next candidate model
        const isModelNotFound =
          error.status === 404 ||
          groqInnerError?.code === "model_not_found" ||
          groqInnerError?.code === "model_decommissioned" ||
          (error.message && (
            error.message.includes("model_not_found") ||
            error.message.includes("model_decommissioned") ||
            error.message.includes("decommissioned")
          ));

        if (!isModelNotFound) {
          throw new LLMProviderError(
            "groq",
            error.message || "Failed to generate Groq response",
            error,
            groqInnerError?.code
          );
        }
      }
    }

    const groqInnerError = lastError?.error?.error;
    throw new LLMProviderError(
      "groq",
      lastError?.message || "Failed to generate Groq response across available models",
      lastError,
      groqInnerError?.code
    );
  }
}

import { prisma } from "../prisma";
import { AI_COST_USD_PER_1M, AI_PRICING_VERSION } from "./config";

import { hasAiRequest } from "./telemetry-runtime";
import type { LLMUsage } from "./providers/types";

export interface AiUsageEntry {
  userId: number;
  feature: "chat" | "planner" | "syllabus" | "other";
  workload?: string | null;
  provider: string;
  model: string;
  promptTokens: number;
  completionTokens: number;
  cacheHitTokens?: number;
}

/** Versioned list-price estimate. Unknown models stay unknown. */
export function estimateCostUsd(
  model: string,
  promptTokens: number,
  completionTokens: number,
  cacheHitTokens = 0
): number | null {
  // New dispatches use current rates only. Historical rows retain stored estimates.
  const canonical = model.startsWith("gemini-2.5-flash-") && !model.includes("lite") ? "gemini-2.5-flash" : model;
  const rate = AI_COST_USD_PER_1M[canonical];
  if (!rate || !Object.values(rate).every(value => Number.isFinite(value) && value >= 0)) return null;

  const totalInput = Math.max(0, promptTokens);
  const hit = Math.min(Math.max(0, cacheHitTokens), totalInput);
  const miss = totalInput - hit;
  const cachedRate = rate.inputCached ?? rate.input * 0.1;

  const cost =
    (miss / 1_000_000) * rate.input +
    (hit / 1_000_000) * cachedRate +
    (Math.max(0, completionTokens) / 1_000_000) * rate.output;
  return Math.round(cost * 1_000_000) / 1_000_000; // 6 decimal places
}

export async function logAiUsage(entry: AiUsageEntry, quiet = false): Promise<void> {
  if (hasAiRequest()) return; // Per-dispatch receipts replace legacy aggregate writes.
  try {
    // Guard: if the AiUsageLog table isn't available (older DB, test mocks),
    // skip silently — telemetry must never affect the chat flow.
    if (!(prisma as any).aiUsageLog) return;

    await prisma.aiUsageLog.create({
      data: {
        userId: entry.userId,
        feature: entry.feature,
        workload: entry.workload ?? null,
        provider: entry.provider,
        model: entry.model,
        promptTokens: Math.max(0, Math.round(entry.promptTokens || 0)),
        completionTokens: Math.max(0, Math.round(entry.completionTokens || 0)),
        cacheHitTokens: Math.max(0, Math.round(entry.cacheHitTokens || 0)),
        estimatedCostUsd: estimateCostUsd(
          entry.model,
          entry.promptTokens,
          entry.completionTokens,
          entry.cacheHitTokens
        ),
      },
    });
  } catch {
    // Telemetry must never break the conversation.
    if (!quiet) console.warn("[AI telemetry] receipt unavailable");
  }
}

export interface AiDispatchEntry {
  userId: number; feature: "chat" | "planner" | "syllabus" | "other"; workload: string;
  provider: string; model: string; requestedModel: string; requestId: string; rootRequestId: string;
  dispatchIndex: number; latencyMs: number; outcome: string; modelVerified: boolean;
  retryIndex?: number; stage?: string;
  usage?: LLMUsage; finishReason?: string; grounding: boolean;
}
export async function logAiDispatch(entry: AiDispatchEntry, phase: "start" | "settle" = "settle"): Promise<void> {
  try {
    const { usage, ...metadata } = entry;
    const known = Boolean(usage);
    const data = {
      ...metadata, finishReason: entry.finishReason?.slice(0, 32),
      latencyMs: phase === "start" ? null : entry.latencyMs,
      promptTokens: usage?.promptTokens ?? 0, completionTokens: usage?.completionTokens ?? 0,
      cacheHitTokens: usage?.cacheHitTokens ?? 0, reasoningTokens: usage?.reasoningTokens ?? null,
      usageKnown: known, cacheUsageKnown: usage?.cacheHitTokens !== undefined,
      accountingState: phase === "start" ? "DISPATCHED" : known ? "SETTLED" : "UNKNOWN_SPEND",
      // Grounding fees/account credits are not inferable from token receipts.
      estimatedCostUsd: usage && !entry.grounding ? estimateCostUsd(entry.model, usage.promptTokens, usage.completionTokens, usage.cacheHitTokens) : null,
      pricingVersion: AI_PRICING_VERSION,
    };
    await prisma.aiUsageLog.upsert({ where: { requestId: entry.requestId }, create: data, update: phase === "start" ? {} : data });
  } catch { console.warn("[AI telemetry] receipt unavailable"); }
}
